package com.eastoftown.pos;
import jakarta.validation.Valid; import jakarta.validation.constraints.*; import java.time.*; import java.util.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class BillingService {
 public record Line(@NotBlank String variantId,@Min(1) @Max(1000) int quantity,@Min(0) long discountPaise){}
 public record Payment(@NotNull Method method,@Min(1) long amountPaise){} public enum Method{CASH,UPI,CARD}
 public record Checkout(@NotEmpty @Size(max=100) List<@Valid Line> lines,@Min(0) long billDiscountPaise,@NotEmpty List<@Valid Payment> payments,String customerName,String customerPhone){}
 final CatalogRepository repo; final StockService stock; public BillingService(CatalogRepository repo,StockService stock){this.repo=repo;this.stock=stock;}
 @Transactional public Object checkout(Checkout input,String actor){String id=UUID.randomUUID().toString(),now=Instant.now().toString();long subtotal=0,discount=input.billDiscountPaise();List<Map<String,Object>> rows=new ArrayList<>();Set<String> seen=new HashSet<>();
  for(Line l:input.lines()){if(!seen.add(l.variantId()))throw new IllegalArgumentException("Add each product once and change its quantity");var found=repo.jdbc().queryForList("SELECT v.*,p.name FROM product_variants v JOIN products p ON p.id=v.product_id WHERE v.id=? AND v.active=1",l.variantId());if(found.isEmpty())throw new IllegalArgumentException("Product variant is missing or inactive");var v=found.getFirst();long available=stock.stock(l.variantId());if(available<l.quantity())throw new IllegalArgumentException("Insufficient stock for "+v.get("name")+" (available: "+available+")");long gross=Math.multiplyExact(((Number)v.get("selling_paise")).longValue(),l.quantity());if(l.discountPaise()>gross)throw new IllegalArgumentException("Line discount cannot exceed line amount");subtotal=Math.addExact(subtotal,gross);discount=Math.addExact(discount,l.discountPaise());rows.add(Map.of("line",l,"v",v,"total",gross-l.discountPaise()));}
  long total=Math.max(0,subtotal-discount),paid=input.payments().stream().mapToLong(Payment::amountPaise).sum();if(paid!=total)throw new IllegalArgumentException("Payment total must equal invoice total");
  repo.jdbc().update("INSERT INTO invoices VALUES (?,?,?,?,?,?,?,?,?,?,?)",id,nextNumber(),"COMPLETED",subtotal,discount,0,total,input.customerName(),input.customerPhone(),actor,now);
  for(var row:rows){Line l=(Line)row.get("line");var v=(Map<String,Object>)row.get("v");repo.jdbc().update("INSERT INTO invoice_items VALUES (?,?,?,?,?,?,?,?,?,?,?)",UUID.randomUUID().toString(),id,l.variantId(),v.get("name"),v.get("sku"),v.get("size"),v.get("colour"),v.get("selling_paise"),l.quantity(),l.discountPaise(),0,row.get("total"));stock.movement(l.variantId(),-l.quantity(),"SALE","Invoice sale",id,actor);}
  for(Payment p:input.payments())repo.jdbc().update("INSERT INTO payments VALUES (?,?,?,?,?)",UUID.randomUUID().toString(),id,p.method().name(),p.amountPaise(),now);repo.jdbc().update("INSERT INTO audit_logs VALUES (?,?,?,?,?)",UUID.randomUUID().toString(),"INVOICE_COMPLETED",id,actor,now);return invoice(id);}
 private String nextNumber(){var rows=repo.jdbc().queryForList("SELECT invoice_number FROM invoices ORDER BY created_at DESC LIMIT 1");int n=1;if(!rows.isEmpty())try{String x=rows.getFirst().get("invoice_number").toString();n=Integer.parseInt(x.substring(x.lastIndexOf('-')+1))+1;}catch(Exception ignored){}return "EOT-"+LocalDate.now(ZoneId.of("Asia/Kolkata")).toString().replace("-","")+"-"+String.format("%05d",n);}
 public Object invoice(String id){var h=repo.jdbc().queryForList("SELECT * FROM invoices WHERE id=?",id);if(h.isEmpty())throw new IllegalArgumentException("Invoice not found");return Map.of("invoice",h.getFirst(),"items",repo.jdbc().queryForList("SELECT * FROM invoice_items WHERE invoice_id=?",id),"payments",repo.jdbc().queryForList("SELECT * FROM payments WHERE invoice_id=?",id));} public Object history(){return repo.jdbc().queryForList("SELECT * FROM invoices ORDER BY created_at DESC LIMIT 500");}
}
